//
// The JavaScript port of wyhash64: the implementation the JavaScript consumers import.
//
// THE REFERENCE IS ZIG'S BUILTIN. `std.hash.Wyhash` is the variant this project treats as the definition,
// because that is the variant the existing Java implementations follow: `hr.hrg.wyhash:wyhash:1.0.0` and
// every copy of it in circulation reproduce `std.hash.Wyhash` value for value, and
// `conformance/wyhash-vectors.json` is generated by `conformance/gen-vectors.zig` from the builtin itself
// (see `WYHASH.md`). A port is correct when it reproduces those vectors, not when it reproduces another
// port.
//
// WHY THE LIBRARY VECTORS ARE ALSO HARD-CODED HERE. The seven values in `LIBRARY_GOLDEN_VECTORS` were
// produced by the LIBRARY rather than by this file:
//
//     hr.hrg.wyhash.Wyhash64.hash(0, bytes)   formatted as %016x, JDK 25
//
// and they are the same vectors `hipster-entity-tooling`'s `ContentHashTest` pins its vendored copy to.
// Zig's builtin agrees with every one of them (measured), which is what makes "the builtin is the
// reference" and "the Java copies are the reference" the same statement rather than a hope. Asserting them
// here means this port is anchored to both sides, and a divergence in either direction fails loudly.

/** The four wyhash secrets, as unsigned 64-bit BigInts. */
const SECRET0 = 0xa0761d6478bd642fn;
const SECRET1 = 0xe7037ed1a0b428dbn;
const SECRET2 = 0x8ebc6af09c88c6e3n;
const SECRET3 = 0x589965cc75374cc3n;

const MASK64 = 0xffffffffffffffffn;

/** `seed` and every 64-bit value in this file are unsigned BigInts in `[0, 2^64)`. */
export const SEED = 0n;

/**
 * Library-produced golden vectors: `{"text": …, "wyhash64": …}`, the value as 16 lowercase hex characters.
 *
 * The 10 800-byte case lives in `conformance/wyhash-vectors.json` rather than here (it is one `text` entry
 * there with the same value), so this table stays readable.
 */
export const LIBRARY_GOLDEN_VECTORS = Object.freeze([
  Object.freeze({ text: '', wyhash64: '0409638ee2bde459' }),
  Object.freeze({ text: 'a', wyhash64: '28d2053309d28531' }),
  Object.freeze({ text: 'line1\nline2\n', wyhash64: '775e9cc0de7360a1' }),
  Object.freeze({ text: '0123456789abcdef', wyhash64: 'c304e72c387cd229' }),
  Object.freeze({ text: '0123456789abcdefg', wyhash64: 'b496f8f306600195' }),
  Object.freeze({ text: '0123456789abcdef0123456789abcdef0123456789abcdef', wyhash64: 'f838bb251f427d71' }),
  Object.freeze({ text: '0123456789abcdef0123456789abcdef0123456789abcdef0', wyhash64: '3fbbd2637f1bb7e0' }),
]);

/** `mix(a, b)`: the low 64 bits of `a * b`, XOR the high 64 bits. */
function mix(a, b) {
  const product = a * b;
  return (product & MASK64) ^ (product >> 64n);
}

/**
 * The 64-bit hash of `bytes` (a `Uint8Array` or `Buffer`) with `seed`, as an unsigned BigInt.
 *
 * The layout follows the reference exactly — including its two quirks that a rewrite from memory gets
 * wrong: the short-input path (`<= 16` bytes) reads two overlapping groups of four bytes whose second
 * offset is `(len >> 3) << 2` rather than a constant, and the final `finish` step mixes the *unsigned* high
 * half of a 128-bit product, which JavaScript has to build from BigInt because `Math.imul` stops at 32
 * bits.
 */
export function wyhash64(bytes, seed = SEED) {
  const length = bytes.length;
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let state = seed ^ mix(seed ^ SECRET0, SECRET1);
  let a;
  let b;

  if (length <= 16) {
    if (length >= 4) {
      const doubled = (length >> 3) << 2;
      a = (BigInt(view.getUint32(0, true)) << 32n) | BigInt(view.getUint32(doubled, true));
      b = (BigInt(view.getUint32(length - 4, true)) << 32n)
        | BigInt(view.getUint32(length - 4 - doubled, true));
    } else if (length > 0) {
      a = BigInt((bytes[0] << 16) | (bytes[length >> 1] << 8) | bytes[length - 1]);
      b = 0n;
    } else {
      a = 0n;
      b = 0n;
    }
  } else {
    let remaining = length;
    let offset = 0;
    let see0 = state;
    let see1 = state;
    let see2 = state;

    while (remaining > 48) {
      see0 = mix(view.getBigUint64(offset, true) ^ SECRET1, view.getBigUint64(offset + 8, true) ^ see0);
      see1 = mix(view.getBigUint64(offset + 16, true) ^ SECRET2, view.getBigUint64(offset + 24, true) ^ see1);
      see2 = mix(view.getBigUint64(offset + 32, true) ^ SECRET3, view.getBigUint64(offset + 40, true) ^ see2);
      offset += 48;
      remaining -= 48;
    }
    see0 ^= see1 ^ see2;
    while (remaining > 16) {
      see0 = mix(view.getBigUint64(offset, true) ^ SECRET1, view.getBigUint64(offset + 8, true) ^ see0);
      remaining -= 16;
      offset += 16;
    }
    a = view.getBigUint64(length - 16, true);
    b = view.getBigUint64(length - 8, true);
    state = see0;
  }

  const left = a ^ SECRET1;
  const right = b ^ state;
  const product = left * right;
  const low = product & MASK64;
  const high = product >> 64n;
  return mix(low ^ SECRET0 ^ BigInt(length), high ^ SECRET1);
}

/** The 16 lowercase hex characters a document or a `files.meta` field carries. */
export function wyhash64Hex(bytes, seed = SEED) {
  return wyhash64(bytes, seed).toString(16).padStart(16, '0');
}

/** The UTF-8 bytes of `text`, hashed: what a name's or a text file's content hash is taken over. */
export function wyhash64Text(text, seed = SEED) {
  return wyhash64(new TextEncoder().encode(text), seed);
}

/** The bytes of a `pattern` case: `byte[i] = (i * 7 + 3) & 0xFF` (WYHASH.md § 4). */
export function patternBytes(length) {
  return Uint8Array.from({ length }, (_, index) => (index * 7 + 3) & 0xff);
}

/**
 * Throws when this implementation disagrees with the library-produced golden vectors.
 *
 * Called by the vector generator before it emits anything, and by this port's own test, so a broken hash
 * cannot become a generated contract.
 */
export function assertLibraryGoldenVectors() {
  const wrong = [];
  for (const vector of LIBRARY_GOLDEN_VECTORS) {
    const actual = wyhash64Hex(new TextEncoder().encode(vector.text));
    if (actual !== vector.wyhash64) {
      wrong.push(`${JSON.stringify(vector.text)}: got ${actual}, library says ${vector.wyhash64}`);
    }
  }
  if (wrong.length > 0) {
    throw new Error(`wyhash64 disagrees with hr.hrg.wyhash:wyhash:1.0.0 on ${wrong.length} vector(s):\n  ${wrong.join('\n  ')}`);
  }
  return LIBRARY_GOLDEN_VECTORS.length;
}